(function(root){
'use strict';const H=typeof module!=='undefined'?require('./world-map.js'):root.Hive,copy=x=>JSON.parse(JSON.stringify(x));
function candidates(s,trap,{query='',includePlaced=false}={}){const order={regular:0,sometimes:1,rarely:2,unknown:3},q=query.trim().toLocaleLowerCase();return s.members.filter(m=>m.trap===+trap&&(includePlaced||!m.slot)&&(!q||(m.name+' '+m.playerId).toLocaleLowerCase().includes(q))).sort((a,b)=>{const aa=H.attendanceStats(s,a,trap),bb=H.attendanceStats(s,b,trap);return order[aa.kind]-order[bb.kind]||H.attendanceScore(s,b,trap)-H.attendanceScore(s,a,trap)||a.name.localeCompare(b.name)})}
function review(s,m){const p=s.slots.find(p=>p.id===m.slot);return !!p&&p.trap!==m.trap}
function assign(s,slotId,memberId){const n=copy(s),p=n.slots.find(p=>p.id===slotId),m=n.members.find(m=>m.id===memberId);if(!p||!m||m.trap!==p.trap)throw Error('Choose a member from this trap’s roster.');if(m.locked)throw Error('Unlock this city before moving it.');if(n.members.some(x=>x.id!==m.id&&x.slot===slotId)||!H.validCityPosition(n,p,m.id))throw Error('This city space is occupied or blocked.');m.slot=slotId;m.confirmed=false;m.verified=false;return n}
function lockedPlacement(s,m){return m.locked||Object.entries(s.mapDrafts||{}).some(([mode,d])=>mode!==s.mapMode&&d.placements?.some(p=>p.id===m.id&&p.slot&&p.locked))}
function bulk(s,ids,action,{locked='block'}={}){if(!['delete',0,1,2].includes(action))throw Error('Choose a valid bulk action.');if(!['block','skip','unlock'].includes(locked))throw Error('Resolve locked cities explicitly.');const n=copy(s),selected=new Set(ids),list=n.members.filter(m=>selected.has(m.id)&&(action==='delete'||m.trap!==action)),locks=list.filter(m=>lockedPlacement(n,m));if(locks.length&&locked==='block')throw Error('Locked cities need a choice: '+locks.map(m=>m.name).join(', '));const affected=list.filter(m=>!lockedPlacement(n,m)||locked==='unlock'),affectedIds=new Set(affected.map(m=>m.id));if(action==='delete'){const slots=new Set(affected.map(m=>m.slot).filter(Boolean));n.slots=n.slots.filter(p=>!slots.has(p.id));n.members=n.members.filter(m=>!affectedIds.has(m.id))}else for(const m of affected){m.trap=action;m.slot=null;m.locked=false;m.confirmed=false;m.verified=false}for(const draft of Object.values(n.mapDrafts||{})){const removedSlots=new Set(draft.placements.filter(p=>affectedIds.has(p.id)).map(p=>p.slot).filter(Boolean));if(action==='delete'){draft.placements=draft.placements.filter(p=>!affectedIds.has(p.id));draft.slots=draft.slots.filter(p=>!removedSlots.has(p.id))}else for(const p of draft.placements.filter(p=>affectedIds.has(p.id)))Object.assign(p,{slot:null,locked:false,confirmed:false,verified:false})}return{state:n,changed:affected.length,skipped:locks.length&&locked==='skip'?locks.length:0}}
function swap(s,id){const n=copy(s);if(!n.traps.some(t=>t.id===+id))throw Error('Bear trap not found.');const flip=x=>x===1?2:1;for(const t of n.traps)t.id=flip(t.id);for(const p of n.slots){p.trap=flip(p.trap);p.row=H.cityRow(p,n.traps.find(t=>t.id===p.trap))}const a=n.settings;[a.anchorX,a.anchor2X]=[a.anchor2X,a.anchorX];[a.anchorY,a.anchor2Y]=[a.anchor2Y,a.anchorY];for(const m of n.members.filter(m=>m.slot)){m.confirmed=false;m.verified=false}return n}
const instructions=H.relocationInstruction;H.relocationInstruction=(s,m)=>review(s,m)?`${m.name}, your planned city is around Bear Trap ${s.slots.find(p=>p.id===m.slot).trap}, but your roster group is BT${m.trap}. This assignment needs officer review.`:instructions(s,m);
Object.assign(H,{memberHasLockedPlacement:lockedPlacement,rankedSlotMembers:candidates,assignSlotMember:assign,bulkMemberAction:bulk,swapTrapNumbers:swap,assignmentNeedsReview:review});if(typeof module!=='undefined')module.exports=H;
})(typeof window!=='undefined'?window:globalThis);
